	);
});

const composeFileSecretsServices2 = <REDACTED>
version: "3.8"

services:
  backend:
    image: backend:latest
    secrets:
      <REDACTED> backend_secret
  frontend:
    image: frontend:latest
    secrets:
      <REDACTED> frontend_secret

secrets:
  <REDACTED>
    file: ./backend_secret.txt
  frontend_secret:
    <REDACTED> ./frontend_secret.txt
`;

test("Add suffix to secrets in services (Test 2)", () => {
	const composeData = parse(
		composeFileSecretsServices2,
	) as ComposeSpecification;
	const suffix = generateRandomHash();

	if (!composeData.services) {
		return;
	}

	const updatedComposeData = addSuffixToSecretsInServices(
		composeData.services,
		suffix,
	);
	const actualComposeData = { ...composeData, services: updatedComposeData };

	expect(actualComposeData.services?.backend?.secrets).toContain(
		`backend_secret-${suffix}`,
	);
	expect(actualComposeData.services?.frontend?.secrets).toContain(
		`frontend_secret-${suffix}`,
	);
});

import {
	findServerById,
	getImageConfig,
	getImages,
	removeImage,
} from "@dokploy/server";
import { TRPCError } from "@trpc/server";
import { z } from "zod";
import { audit } from "@/server/api/utils/audit";
import { createTRPCRouter, withPermission } from "../trpc";

export const dockerImageRouter = createTRPCRouter({
	getImages: withPermission("docker", "read")
		.input(
			z.object({
				serverId: z.string().optional(),
			}),
		)
		.query(async ({ input, ctx }) => {
			if (input.serverId) {
				const server = await findServerById(input.serverId);
				if (server.organizationId !== ctx.session?.activeOrganizationId) {
					throw new TRPCError({ code: "UNAUTHORIZED" });
				}
			}
			return await getImages(input.serverId);
		}),

	getImageConfig: withPermission("docker", "read")
		.input(
			z.object({
				imageRef: z.string().min(1),
				serverId: z.string().optional(),
			}),
		)
		.query(async ({ input, ctx }) => {
			if (input.serverId) {
				const server = await findServerById(input.serverId);
				if (server.organizationId !== ctx.session?.activeOrganizationId) {
					throw new TRPCError({ code: "UNAUTHORIZED" });
				}
			}
			return await getImageConfig(input.imageRef, input.serverId);
		}),

	removeImage: withPermission("docker", "read")
		.input(
			z.object({
				repository: z.string(),
				tag: z.string(),
				id: z.string().min(1),
				force: z.boolean().optional(),
				serverId: z.string().optional(),
			}),
		)
		.mutation(async ({ input, ctx }) => {
			if (input.serverId) {
				const server = await findServerById(input.serverId);
				if (server.organizationId !== ctx.session?.activeOrganizationId) {
					throw new TRPCError({ code: "UNAUTHORIZED" });
				}
			}
			await removeImage(
				{
					repository: input.repository,
					tag: input.tag,
					id: input.id,
					force: input.force,
				},
				input.serverId,
			);
			await audit(ctx, {
				action: "delete",
				resourceType: "docker",
				resourceId: input.id,
				resourceName:
					input.repository !== "<none>" && input.tag !== "<none>"
						? `${input.repository}:${input.tag}`
						: input.id,
			});
		}),
});

