						source: `${secret.source}-${suffix}`,
					};
				}
				return secret;
			});
		}

		newServices[serviceName] = newServiceConfig;
	});

	return newServices;
};

export const addSuffixToAllSecrets = <REDACTED>
	composeData: ComposeSpecification,
